B.PT=new A.dZ("blink","Blink an LED","Blink LED","Basics","Beginner","Switch the built-in LED on and off.","The first sketch everyone runs","V2 \xb7 Uno \xb7 ESP32",'// Blink \u2014 RoboCore V2\n// Turns the built-in LED on and off every second.\n\nvoid setup() {\n  Serial.begin(115200);\n  Serial.println("RoboCore V2 ready");\n  pinMode(LED_BUILTIN, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(LED_BUILTIN, HIGH);\n  delay(1000);\n  digitalWrite(LED_BUILTIN, LOW);\n  delay(1000);\n}\n',"Blink",B.XA,"Blink",null,null)
B.PX=new A.dZ("button","Button-controlled LED","Button LED","Basics","Beginner","Light the LED while USER is pressed.","Read a button, drive an LED","V2 \xb7 Uno \xb7 ESP32","// Button-controlled LED\n// Lights the built-in LED while the USER button is held down.\n#define USER_BUTTON 0\n\nvoid setup() {\n  pinMode(LED_BUILTIN, OUTPUT);\n  pinMode(USER_BUTTON, INPUT_PULLUP);\n}\n\nvoid loop() {\n  bool pressed = digitalRead(USER_BUTTON) == LOW;\n  digitalWrite(LED_BUILTIN, pressed ? HIGH : LOW);\n  delay(10);\n}\n",null,null,"ButtonLed",null,null)
