B.PR=new A.dZ("melody","Buzzer melody","Buzzer melody","Sound & light","Beginner","Play a short tune note by note.","Play a tune with tone()","V2 \xb7 Uno \xb7 ESP32","// Buzzer melody\n// Plays a short tune on the buzzer (pin 8).\nconst int BUZZER = 8;\n\nvoid note(int freq, int ms) {\n  tone(BUZZER, freq, ms);\n  delay(ms + 50);\n}\n\nvoid setup() {\n  pinMode(BUZZER, OUTPUT);\n}\n\nvoid loop() {\n  note(262, 400);\n  note(262, 400);\n  note(392, 400);\n  note(392, 400);\n  note(440, 400);\n  note(440, 400);\n  note(392, 800);\n  noTone(BUZZER);\n  delay(1500);\n}\n",null,B.Xy,"BuzzerMelody",B.Xw,null)
B.PJ=new A.dZ("rgb","RGB colour cycle","RGB colours","Sound & light","Beginner","Step the RGB LED through red, green and blue.","The on-board RGB LED","RoboCore V2","// RGB colour cycle\n// Steps the on-board RGB LED through a few colours.\n\nvoid setup() {\n}\n\nvoid loop() {\n  rgbLedWrite(RGB_BUILTIN, 255, 0, 0);    // red\n  delay(500);\n  rgbLedWrite(RGB_BUILTIN, 0, 255, 0);    // green\n  delay(500);\n  rgbLedWrite(RGB_BUILTIN, 0, 0, 255);    // blue\n  delay(500);\n  rgbLedWrite(RGB_BUILTIN, 255, 160, 0);  // amber\n  delay(500);\n}\n",null,null,"RgbColours",null,null)
