B.PU=new A.dZ("logger","Sensor logger","Sensor logger","Sensors","Intermediate","Log an analog sensor as CSV with timestamps.","CSV over serial","V2 \xb7 Uno \xb7 ESP32",'// Sensor logger\n// Logs a light sensor on pin 34 as CSV, once a second.\nconst int LIGHT_PIN = 34;\n\nvoid setup() {\n  Serial.begin(115200);\n  Serial.println("time_ms,light");\n}\n\nvoid loop() {\n  int light = analogRead(LIGHT_PIN);\n  Serial.print(millis());\n  Serial.print(",");\n  Serial.println(light);\n  delay(1000);\n}\n',null,null,"SensorLogger",null,null)
B.PN=new A.dZ("echo","Serial echo","Serial echo","Communication","Intermediate","Reply to text you send from the Serial Monitor.","Talk to your board","V2 \xb7 Uno \xb7 ESP32",'// Serial echo\n// Replies to each line you send from the Serial Monitor.\n\nvoid setup() {\n  Serial.begin(115200);\n  Serial.println("Type something and press Send");\n}\n\nvoid loop() {\n  if (Serial.available() > 0) {\n    String msg = Serial.readStringUntil(\'\\n\');\n    msg.trim();\n    Serial.print("You said: ");\n    Serial.println(msg);\n    if (msg == "led on") {\n      digitalWrite(LED_BUILTIN, HIGH);\n    }\n    if (msg == "led off") {\n      digitalWrite(LED_BUILTIN, LOW);\n    }\n  }\n  delay(20);\n}\n',null,null,"SerialEcho",null,null)
